command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="b414e8e3f8eb5e6c771c1f41ba4e632c143b1db4"
$candidate="d41a75cac8a2eb40dc406174c07689ad6e54f063"
$branch="work/shell-provider-visuals-20261007"
$beforeHash="ac462537fd94437161c2033a927806b170045e18da5573bfdc8ca8f6c4a79005"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "provider visual fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before provider visual validation"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "provider visual candidate mismatch"}
$dirty=@(& git status --porcelain=v1 -uall)
if($dirty.Count -ne 0){$dirty|%{Write-Host ("UNEXPECTED_WORKTREE="+$_)};throw "persistent checkout is dirty"}
$before=Join-Path $repo "logs\shell-provider-visual\shell-provider-visual-before.bmp"
if(-not(Test-Path -LiteralPath $before -PathType Leaf)){throw "accepted provider BEFORE is missing"}
if((Get-FileHash -Algorithm SHA256 $before).Hash.ToLowerInvariant() -ne $beforeHash){throw "provider BEFORE hash changed"}
& git switch --detach $candidate
if($LASTEXITCODE -ne 0){throw "provider visual candidate checkout failed"}
& .\build.bat Release
if($LASTEXITCODE -ne 0){throw "provider visual Release build failed"}
& python -X utf8 tests\winui\test_shell_provider_visual_gui.py --configuration Release --capture after --expect-provider-visual
if($LASTEXITCODE -ne 0){throw "provider type/icon focused GUI failed"}
$after=Join-Path $repo "logs\shell-provider-visual\shell-provider-visual-after.bmp"
if(-not(Test-Path -LiteralPath $after -PathType Leaf)){throw "provider AFTER capture missing"}
$evidence=Join-Path $repo "logs\remote-evidence"
New-Item -ItemType Directory -Force -Path $evidence|Out-Null
Copy-Item -LiteralPath $before -Destination (Join-Path $evidence "shell-provider-visual-before.bmp") -Force
Copy-Item -LiteralPath $after -Destination (Join-Path $evidence "shell-provider-visual-after.bmp") -Force
Write-Host ("SHELL_PROVIDER_AFTER_SHA256="+(Get-FileHash -Algorithm SHA256 $after).Hash.ToLowerInvariant())
& git switch main
if($LASTEXITCODE -ne 0){throw "failed to restore main after provider visual validation"}
& git merge --ff-only origin/main
if($LASTEXITCODE -ne 0){throw "failed to fast-forward main after provider visual validation"}
Write-Host "SHELL_PROVIDER_TYPE_ICON_VALIDATION=PASS"
